test('suppression: no estimate and no flags while on; a cycle across it is not counted; "no period" counts from the day it ended', () => {
  const on = cycleSummary([...regular(), old('2026-10-25', 'suppression_on')], NOW);
  assert.equal(on.suppressed, true);
  assert.equal(on.nextExpected, null);
  assert.deepEqual(on.flags, []);
  const after = cycleSummary([...days('2026-03-01', ['medium', 'light']), old('2026-03-10', 'suppression_on'), old('2026-10-01', 'suppression_off'), ...days('2026-10-20', ['medium', 'light'])], NOW);
  assert.deepEqual(after.lengths, [], 'March to October is not a cycle: periods were suppressed in between');
  assert.equal(after.periods[0].acrossSuppression, true);
  assert.equal(after.cycleDay, 27);
  const quiet = cycleSummary([...days('2026-03-01', ['medium', 'light']), old('2026-03-10', 'suppression_on'), old('2026-10-01', 'suppression_off')], NOW);
  assert.deepEqual(quiet.flags, [], 'no period since suppression ended 45 days ago: not yet 3 months');
  assert.equal(quiet.cycleDay, null);
  assert.match(cycleFacts(quiet)[0], /stopped suppressing your periods on Thu 1 Oct 2026/);
  const later = cycleSummary([...days('2026-03-01', ['medium', 'light']), old('2026-03-10', 'suppression_on'), old('2026-07-01', 'suppression_off')], NOW);
  assert.ok(later.flags.includes('no-period'), 'more than 3 months since suppression ended (Endocrine Society)');
  const bleedDuring = cycleSummary([old('2026-06-01', 'suppression_on'), ...days('2026-10-02', ['spotting', 'light'])], NOW);
  assert.equal(bleedDuring.periods.length, 0, 'bleeding while suppressed is breakthrough bleeding, not a period');
  const undone = cycleSummary([...regular(), old('2026-11-15', 'suppression_on', '07'), { time: '2026-11-15T07:01:00.000Z', value: 'suppression_off' }], NOW);
  assert.deepEqual([undone.suppressed, undone.suppressedSince, undone.cycleDay, dayOf(undone.nextExpected)], [false, false, 32, '2026-11-12'], 'switched on and off on the same day: a tap undone, nothing changes');
});

test('bleeding while suppressed over the last 90 days, in the words of Creinin and others (2022)', () => {
  const base = [old('2026-06-01', 'suppression_on')];
  const none = bleedingSummary(readLog(base), NOW);
  assert.deepEqual([none.full, none.episodes, none.pattern], [true, 0, 'none']);
  const two = bleedingSummary(readLog([...base, ...days('2026-09-01', ['spotting', 'light']), entry('2026-10-10', 'spotting')]), NOW);
  assert.deepEqual([two.episodes, two.bleedingDays, two.spottingDays, two.pattern, two.prolonged], [2, 1, 2, 'infrequent', false]);
  const many = bleedingSummary(readLog([...base, ...['2026-08-20', '2026-09-01', '2026-09-10', '2026-09-20', '2026-10-01'].map((d) => entry(d, 'spotting'))]), NOW);
  assert.equal(many.pattern, 'frequent', 'more than 4 episodes');
  const long = bleedingSummary(readLog([...base, ...days('2026-10-01', Array(8).fill('light'))]), NOW);
  assert.equal(long.prolonged, true, 'an episode of more than 7 days');
  const recent = bleedingSummary(readLog([old('2026-11-01', 'suppression_on'), entry('2026-11-10', 'spotting')]), NOW);
  assert.deepEqual([recent.full, recent.suppressedDays, recent.pattern], [false, 15, null], 'the pattern words need a whole 90 days of suppression');
  assert.match(cycleFacts(cycleSummary([old('2026-11-01', 'suppression_on'), entry('2026-11-10', 'spotting')], NOW)).join(' '), /Bleeding while suppressed \(on 15 of the last 90 days\): 0 days of bleeding and 1 of spotting, in 1 episode\./);
  assert.match(cycleFacts(cycleSummary([...base, ...days('2026-09-01', ['spotting', 'light'])], NOW)).join(' '), /Bleeding while suppressed \(over the last 90 days\): 1 day of bleeding and 1 of spotting, in 1 episode; infrequent: 2 episodes or fewer in 90 days\./);
  assert.match(cycleFacts(cycleSummary(base, NOW)).join(' '), /No bleeding or spotting logged while suppressed \(over the last 90 days\)\./);
  assert.equal(suppressedOn('2026-10-31', readLog([old('2026-11-01', 'suppression_on')]).suppression), false);
});

